import{_ as s,o as e,c as n,a0 as i}from"./chunks/framework.BpJS36ta.js";const k=JSON.parse('{"title":"Spec — konfigurasi proyek","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/spec.md","filePath":"syntax/spec.md"}'),p={name:"syntax/spec.md"};function t(l,a,d,r,o,c){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="spec-—-konfigurasi-proyek" tabindex="-1">Spec — konfigurasi proyek <a class="header-anchor" href="#spec-—-konfigurasi-proyek" aria-label="Permalink to &quot;Spec — konfigurasi proyek&quot;">​</a></h1><p>Konfigurasi proyek <code>.spec</code> mengikuti <code>rupa go</code> — data proyek, target compile, server dev, sampai kredensial database.</p><h2 id="apa-yang-bisa-ditulis" tabindex="-1">Apa yang bisa ditulis? <a class="header-anchor" href="#apa-yang-bisa-ditulis" aria-label="Permalink to &quot;Apa yang bisa ditulis?&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rupa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # generate .spec.example target web</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rupa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # target lain: android, software, ios</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rupa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # enkripsi .spec.example -&gt; .spec (default sha512)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rupa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sha256</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # dengan algo lain</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rupa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # decrypt .spec kembali ke .spec.example</span></span></code></pre></div><h2 id="kapan-digunakan" tabindex="-1">Kapan digunakan? <a class="header-anchor" href="#kapan-digunakan" aria-label="Permalink to &quot;Kapan digunakan?&quot;">​</a></h2><p>Saat proyek class dibuat dan dijalankan lewat <code>rupa go</code>. <code>.spec.example</code> adalah templat plaintext untuk diisi nilai asli; <code>.spec</code> adalah konfigurasi yang dibaca <code>rupa go</code> saat eksekusi.</p><h2 id="apa-hasilnya" tabindex="-1">Apa hasilnya? <a class="header-anchor" href="#apa-hasilnya" aria-label="Permalink to &quot;Apa hasilnya?&quot;">​</a></h2><p><code>rupa spec web</code> menghasilkan <code>.spec.example</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name: your app name</span></span>
<span class="line"><span>author: -</span></span>
<span class="line"><span>version: &quot;1.0&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>target: web</span></span>
<span class="line"><span>arch: unknown</span></span>
<span class="line"><span>debug: true</span></span>
<span class="line"><span>release: false</span></span>
<span class="line"><span>domain: example.com</span></span>
<span class="line"><span>settings:</span></span>
<span class="line"><span>  - host: 127.0.0.1</span></span>
<span class="line"><span>  - port: 8000</span></span>
<span class="line"><span>  - protocol: http</span></span>
<span class="line"><span>  - dbhost: 127.0.0.1</span></span>
<span class="line"><span>  - dbport: 5432</span></span>
<span class="line"><span>  - dbname: app</span></span>
<span class="line"><span>  - dbuser: -</span></span>
<span class="line"><span>  - dbpass: -</span></span>
<span class="line"><span>  - vps:</span></span>
<span class="line"><span>    - settingan vps</span></span></code></pre></div><p>Isi nilai asli di file itu, lalu <code>rupa spec -e</code> mengenkripsinya menjadi <code>.spec</code> — password diminta dua kali (hidden, tidak muncul di layar):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rupa-spec-enc: sha512</span></span>
<span class="line"><span>check: &lt;16 hex digest plaintext&gt;</span></span>
<span class="line"><span>&lt;hex payload&gt;</span></span></code></pre></div><p>Format <code>.spec</code> sama dengan <code>.spec.example</code> (parser yang sama), jadi mengenkripsi tidak mengubah arti konfigurasi — <code>rupa go</code> yang menemukan header <code>rupa-spec-enc:</code> akan meminta password dulu, dan <strong>berhenti bila password salah</strong> (tidak jalan dengan nilai default).</p><h3 id="settings-database-dan-server" tabindex="-1">settings: database dan server <a class="header-anchor" href="#settings-database-dan-server" aria-label="Permalink to &quot;settings: database dan server&quot;">​</a></h3><p>Kredensial database (<code>dbhost/dbport/dbname/dbuser/dbpass</code>) dan server (<code>host/port/protocol</code>, daftar <code>vps</code>) hidup di section <code>settings:</code>. Inilah alasan utama enkripsi: <code>.spec</code> yang mengandung kredensial asli tidak boleh terbaca sembarangan — kasus yang sama dengan <code>.env</code> yang tidak sengaja ter-upload.</p><h3 id="kebijakan-upload" tabindex="-1">Kebijakan upload <a class="header-anchor" href="#kebijakan-upload" aria-label="Permalink to &quot;Kebijakan upload&quot;">​</a></h3><ul><li><code>.spec.example</code> — plaintext, aman di-upload.</li><li><code>.spec</code> — boleh di-upload mau bentuk encrypted atau tidak, terserah Anda; mau aman ya encrypted sebelum upload.</li></ul><h3 id="mode-dev-build-rupa-go" tabindex="-1">Mode dev / build (rupa go) <a class="header-anchor" href="#mode-dev-build-rupa-go" aria-label="Permalink to &quot;Mode dev / build (rupa go)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rupa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # debug=true, release=false; cari serve.rp,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # tanpa itu jalankan server default dari .spec.settings</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rupa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # debug=false, release=true (emisi target menyusul)</span></span></code></pre></div><p>Target tidak perlu ditulis — dibaca dari <code>target:</code> di <code>.spec</code> (<code>rupa go web dev</code> juga masih diterima).</p><h3 id="catatan" tabindex="-1">Catatan <a class="header-anchor" href="#catatan" aria-label="Permalink to &quot;Catatan&quot;">​</a></h3><ul><li>Password tidak disimpan di mana pun; lupa password = <code>.spec</code> harus di-generate ulang dari <code>.spec.example</code>.</li><li><code>rupa spec -d</code> menulis <code>.spec.example</code>, kecuali file itu sudah ada — hasilnya ke <code>.spec.example.out</code> agar tidak menimpa diam-diam.</li><li>Enkripsi berbasis hash (key = H(password)); cukup untuk menyembunyikan konfigurasi dari pembacaan kasual, bukan penyimpanan jangka panjang materi yang sangat sensitif.</li></ul>`,21)])])}const u=s(p,[["render",t]]);export{k as __pageData,u as default};
